package com.mygo.music;
import android.app.*;
import android.content.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Real WebView calls, Android Keystore ciphertext, instance isolation and system proxy selection. */
final class PluginSecureChecks {
 final Instrumentation test;final Context context;final CompletionChecks helper;
 PluginSecureChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helper=new CompletionChecks(test);}
 String call(PluginManager manager,String id,String fn)throws Exception{CountDownLatch done=new CountDownLatch(1);boolean[] ok={false};String[] result={""};manager.export(id,fn,new JSONObject(),(success,raw)->{ok[0]=success;result[0]=raw;done.countDown();});if(!done.await(15,TimeUnit.SECONDS)||!ok[0])throw new AssertionError("secure host call "+fn+": "+result[0]);return result[0];}
 void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 void run()throws Exception{String id="secure-host-fixture";helper.cleanup(id);PluginManager manager=new PluginManager(context);java.net.ProxySelector prior=ProxySelector.getDefault();try{String code="export function put(){host.secrets.set('cookie',{token:'fixture-private-value',flag:true});return host.secrets.get('cookie');}export function read(){return host.secrets.get('cookie');}export function missing(){return host.secrets.get('absent')===undefined;}export function remove(){host.secrets.remove('cookie');return host.secrets.get('cookie')===undefined;}export function route(){return host.proxy('https://music.youtube.com/');}export function httpRoute(){return host.proxy('https://music.youtube.com/','http');}export function badRoute(){try{host.proxy('file:///tmp/data');return false;}catch(e){return true;}}";helper.install(manager,id,"stream",new JSONArray(),code);check(call(manager,id,"missing").equals("true"),"absent secure value was not undefined");check(new JSONObject(call(manager,id,"put")).getString("token").equals("fixture-private-value"),"native secure JSON did not round trip");PluginSecrets secrets=new PluginSecrets(context,id);SharedPreferences records=(SharedPreferences)FullPortChecks.field(secrets,"records");String first=records.getString("cookie","");check(!first.contains("fixture-private-value")&&new JSONObject(first).has("cipher"),"plaintext credential persisted");manager.close();manager=new PluginManager(context);check(new JSONObject(call(manager,id,"read")).getBoolean("flag"),"new runtime lost secure credential");call(manager,id,"put");String second=records.getString("cookie","");check(!first.equals(second),"AES-GCM nonce was reused");records.edit().putString("different",second).commit();try{secrets.get("different");throw new AssertionError("ciphertext could be moved to another key");}catch(IOException expected){}PluginSecrets other=new PluginSecrets(context,id+"-other");SharedPreferences otherRecords=(SharedPreferences)FullPortChecks.field(other,"records");otherRecords.edit().putString("cookie",second).commit();try{other.get("cookie");throw new AssertionError("ciphertext crossed plugin instances");}catch(IOException expected){}otherRecords.edit().clear().commit();check(new JSONObject(call(manager,id,"read")).getString("token").equals("fixture-private-value"),"failed secure reads damaged original credential");
 ProxySelector.setDefault(new ProxySelector(){public java.util.List<Proxy> select(URI uri){return Arrays.asList(new Proxy(Proxy.Type.HTTP,InetSocketAddress.createUnresolved("127.0.0.1",18990)));}public void connectFailed(URI u,SocketAddress a,IOException e){}});check(call(manager,id,"route").equals("\"http://127.0.0.1:18990\"")&&call(manager,id,"httpRoute").equals("\"http://127.0.0.1:18990\""),"host proxy ignored effective HTTP policy");check(call(manager,id,"badRoute").equals("true"),"non-network proxy target accepted");check(call(manager,id,"remove").equals("true"),"source sign out did not remove secure value");records.edit().clear().commit();System.out.println("MYGO_SECURE_HOST_OK keystore=true freshNonces=true scopedAAD=true newRuntime=true systemProxy=true");
 }finally{ProxySelector.setDefault(prior);manager.close();helper.cleanup(id);}}
}
